// length of the input array.

#include "fft.h"

// Function to apply FFT to a strided input array
void apply_strided_fft(const double *input, double *output, size_t n, size_t stride) {
    // Apply FFT to the strided input array
    for (size_t k = 0; k < n; k++) {
        output[k] = 0.0;
        for (size_t m = 0; m < n; m++) {
            double angle = -2.0 * M_PI * k * m / (double)n;
            output[k] += input[m * stride] * (cos(angle) - I*sin(angle));
